-- =====================================================================
-- supabase/seed/olive-n-spice.sql
-- SIRF Olive 'n Spice ke liye, idempotent (dobara chalane par safe).
-- Napoli ki koi row yahan nahi chhoo'ti: har insert/update fixed Olive UUIDs par hai.
--
-- Is mein: (a) restaurant row  (b) menu: categories, items, sizes, options.
-- Is mein NAHI: restaurant_tables (tables ka data baad mein), delivery_mode /
-- delivery_areas (P9a-B / 0022 migration baad mein ayegi), menu photos.
--
-- Dobara chalane par: owner ki settings (is_accepting_orders, delivery_fee,
-- min_order_value, tax, service charge, max discount) aur items/options ka
-- is_available OVERWRITE NAHI hota; baaqi (naam, qeemat, tasveer-free text) menu.ts se
-- dobara set hota hai.
--
-- TODO (owner se confirm karna): menu ke footnote mein likha hai "Service charges 7%.
-- All prices are exclusive of govt. taxes." Abhi service_charge_percent = 0 aur
-- tax_rate_percent = 0 rakhe hain; owner Settings page se khud barhayega.
--
-- Qeematein PKR mein hain (poore rupay). menu_items.base_price = pehli/chhoti qeemat;
-- sizes wali cheezon ke asal rates item_sizes mein hain (koi size default nahi, taake
-- agent/POS size poochhe). CONFIRM wali cheezein is_available = false hain.
-- =====================================================================

begin;

-- ---------- (a) restaurant ----------
  id, name, phone, address_line, city, postcode, timezone, currency,
  is_accepting_orders, opening_hours, delivery_radius_miles, delivery_fee, min_order_value,
  tagline, parent_group_name,
  theme_primary, theme_accent, theme_secondary, theme_background, theme_text,
  tax_rate_percent, service_charge_percent, service_charge_applies_to, max_discount_percent,
  logo_url, whatsapp_number, website_url, instagram_handle, facebook_url, rounding_step
) values (
  '22222222-2222-2222-2222-222222222222',
  'Olive ''n Spice',
  '0313 7179700',
  'Lahore Road, beside Golden Palm',
  'Sargodha',
  null,
  'Asia/Karachi',
  'PKR',
  false,
  '{
    "mon": [{"open": "00:00", "close": "00:00"}],
    "tue": [{"open": "00:00", "close": "00:00"}],
    "wed": [{"open": "00:00", "close": "00:00"}],
    "thu": [{"open": "00:00", "close": "00:00"}],
    "fri": [{"open": "00:00", "close": "00:00"}],
    "sat": [{"open": "00:00", "close": "00:00"}],
    "sun": [{"open": "00:00", "close": "00:00"}]
  }'::jsonb,
  null,
  0,
  0,
  'The art of fine dining',
  'Golden Palm',
  '#556b3f', '#c9a227', '#8fa377', '#faf6ec', '#1a1a1a',
  0, 0, 'none', 0,
  '/brand/olive-n-spice-logo.png',
  '0313 7179700',
  'https://olive-n-spice.vercel.app',
  'olivenspice_',
  'https://www.facebook.com/theolivenspice/',
  1
)
on conflict (id) do update set
  name              = excluded.name,
  phone             = excluded.phone,
  address_line      = excluded.address_line,
  city              = excluded.city,
  timezone          = excluded.timezone,
  currency          = excluded.currency,
  opening_hours     = excluded.opening_hours,
  tagline           = excluded.tagline,
  parent_group_name = excluded.parent_group_name,
  theme_primary     = excluded.theme_primary,
  theme_accent      = excluded.theme_accent,
  theme_secondary   = excluded.theme_secondary,
  theme_background  = excluded.theme_background,
  theme_text        = excluded.theme_text,
  logo_url          = excluded.logo_url,
  whatsapp_number   = excluded.whatsapp_number,
  website_url       = excluded.website_url,
  instagram_handle  = excluded.instagram_handle,
  facebook_url      = excluded.facebook_url,
  rounding_step     = excluded.rounding_step;
  -- NOT updated on purpose (owner controls them): is_accepting_orders, delivery_fee,
  -- delivery_radius_miles, min_order_value, tax_rate_percent, service_charge_percent,
  -- service_charge_applies_to, max_discount_percent.

-- ---------- (b) menu categories (21) ----------
on conflict (id) do update set
  name       = excluded.name,
  sort_order = excluded.sort_order;

-- ---------- menu items (96); is_available = false where menu.ts says CONFIRM ----------
on conflict (id) do update set
  category_id = excluded.category_id,
  name        = excluded.name,
  description = excluded.description,
  base_price  = excluded.base_price,
  spice_level = excluded.spice_level,
  sort_order  = excluded.sort_order;
  -- is_available is NOT updated on purpose.

-- ---------- item sizes (38); absolute prices, no default size ----------
on conflict (id) do update set
  menu_item_id = excluded.menu_item_id,
  name         = excluded.name,
  price        = excluded.price,
  sort_order   = excluded.sort_order;

-- ---------- item options (28): sides, spice level, fish crackers, pizza toppings per size ----------
on conflict (id) do update set
  menu_item_id = excluded.menu_item_id,
  category_id  = excluded.category_id,
  group_name   = excluded.group_name,
  name         = excluded.name,
  price_delta  = excluded.price_delta,
  max_select   = excluded.max_select;
  -- is_available is NOT updated on purpose.

commit;

-- ---------- NOT run: delivery areas (example only) ----------
-- Delivery areas P9a-B (0022 migration) ke baad, owner ki list se banengi. Misaal:
--   insert into public.delivery_areas (id, restaurant_id, name, fee, min_order_value)
--   values ('2222e000-0000-4000-8000-000000000001', '22222222-2222-2222-2222-222222222222', 'Satellite Town', 100, 1000)
--   on conflict (id) do update set name = excluded.name, fee = excluded.fee, min_order_value = excluded.min_order_value;
-- (column ke naam 0022 ke mutabiq badal sakte hain)

